1439: Check("a harmful press cancels following but an off-contact held mouse preserves independent movement",()=>
1440: {
1441:     // Preserve c08's original default negative target and 1.5-second sequence as
1442:     // a separate control. The hand on the right must not force obedience again.
1443:     var sim=Fresh();var c=sim.Selected!;sim.State.Creatures.RemoveAll(o=>o.Id!=c.Id);sim.State.RoomObjects.Clear();c.X=c.Z=0;c.Fullness=90;
1444:     double targetX=c.TargetX,targetZ=c.TargetZ,initialDistance=WorldSimulation.Distance(c.X,c.Z,targetX,targetZ);
1445:     Require(targetX<0,"control lost the original independent walking target");
1446:     sim.SetInteractionHand(3,0,true);c.Interaction.FollowPlayer=true;c.Interaction.Hydration=90;
1447:     var input=new InteractionInput(InteractionAction.Press,BodyPart.Side,Force:.3,Duration:.1);
1448:     double before=c.Health;sim.BeginInteractionGesture(c.Id,input);sim.ContinueInteractionGesture(input,true);double health=c.Health;
1449:     Require(health<before&&!c.Interaction.FollowPlayer,"initial real damage did not interrupt following");
1450:     sim.ContinueInteractionGesture(input,false);double travel=0;
1451:     for(int frame=0;frame<15;frame++)
1452:     {
1453:         double x=c.X,z=c.Z;sim.SetInteractionHand(3,0,true);Tick(sim,1);
1454:         travel+=WorldSimulation.Distance(x,z,c.X,c.Z);
1455:     }
1456:     string diagnostics=JsonSerializer.Serialize(new{c.X,c.Z,c.TargetX,c.TargetZ,c.Activity,c.Health,health,c.Interaction.FollowPlayer,travel,
1457:         pose=InteractionPresentation.Pose(c),sim.HasInteractionGesture,sim.InteractionGestureOwnsPose});
1458:     Console.WriteLine("OFF_CONTACT_INDEPENDENT "+diagnostics);
1459:     Require(travel>.1&&WorldSimulation.Distance(c.X,c.Z,targetX,targetZ)<initialDistance&&c.X<0,
1460:         "independent movement was lost or redirected to the hand: "+diagnostics);
1461:     Require(c.Health>=health&&!c.Interaction.FollowPlayer&&sim.HasInteractionGesture&&!sim.InteractionGestureOwnsPose&&InteractionPresentation.Pose(c)!="pressure",
1462:         "off-contact input damaged, deformed or forced following: "+diagnostics);
1463:     sim.EndInteractionGesture();
1464: });
